ALTER TABLE "PERSONAS"
    ADD COLUMN IF NOT EXISTS "FECHA_NACIMIENTO" DATE,
    ADD COLUMN IF NOT EXISTS "GENERO" VARCHAR(30);

ALTER TABLE "PROFESORES"
    ADD COLUMN IF NOT EXISTS "TITULO_PROFESIONAL" VARCHAR(180),
    ADD COLUMN IF NOT EXISTS "TIPO_CONTRATO" VARCHAR(80) DEFAULT 'Jornada completa',
    ADD COLUMN IF NOT EXISTS "HORAS_SEMANALES" INTEGER DEFAULT 38,
    ADD COLUMN IF NOT EXISTS "FECHA_INGRESO" DATE,
    ADD COLUMN IF NOT EXISTS "ESTADO_DOCENTE" VARCHAR(40) DEFAULT 'Activo';

CREATE TABLE IF NOT EXISTS "PROFESOR_ASIGNATURAS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PROFESOR_ID" BIGINT NOT NULL,
    "ASIGNATURA_ID" BIGINT NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "FK_PROFESOR_ASIGNATURAS_PROFESOR" FOREIGN KEY ("PROFESOR_ID") REFERENCES "PROFESORES" ("ID"),
    CONSTRAINT "FK_PROFESOR_ASIGNATURAS_ASIGNATURA" FOREIGN KEY ("ASIGNATURA_ID") REFERENCES "ASIGNATURAS" ("ID")
);

CREATE TABLE IF NOT EXISTS "PROFESOR_CONTACTOS_EMERGENCIA" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PROFESOR_ID" BIGINT NOT NULL,
    "NOMBRE_COMPLETO" VARCHAR(160) NOT NULL,
    "RELACION" VARCHAR(80) NOT NULL,
    "TELEFONO" VARCHAR(40) NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "FK_PROFESOR_CONTACTO_PROFESOR" FOREIGN KEY ("PROFESOR_ID") REFERENCES "PROFESORES" ("ID")
);

