INSERT INTO "PROFESORES" ("CODIGO", "PERSONA_ID", "ESPECIALIDAD", "TITULO_PROFESIONAL", "TIPO_CONTRATO", "HORAS_SEMANALES", "FECHA_INGRESO", "ESTADO_DOCENTE", "ACTIVO")
SELECT * FROM (
    SELECT 'PROF-001', p."ID", 'Prof. Matematica y Ciencias', 'Prof. de Matematicas y Ciencias', 'Jornada completa', 38, DATE '2020-03-01', 'Activo', TRUE
    FROM "PERSONAS" p WHERE p."RUN" = '12.345.678-9'
    UNION ALL
    SELECT 'PROF-002', p."ID", 'Prof. Lenguaje e Historia', 'Prof. de Lenguaje e Historia', 'Jornada completa', 38, DATE '2019-03-01', 'Activo', TRUE
    FROM "PERSONAS" p WHERE p."RUN" = '13.456.789-0'
    UNION ALL
    SELECT 'PROF-003', p."ID", 'Prof. Artes y Musica', 'Prof. de Artes y Musica', 'Media jornada', 22, DATE '2021-03-10', 'Activo', TRUE
    FROM "PERSONAS" p WHERE p."RUN" = '14.567.890-1'
    UNION ALL
    SELECT 'PROF-004', p."ID", 'Prof. Ingles', 'Prof. de Ingles', 'Jornada completa', 38, DATE '2022-03-07', 'Activo', TRUE
    FROM "PERSONAS" p WHERE p."RUN" = '15.678.901-2'
    UNION ALL
    SELECT 'PROF-005', p."ID", 'Prof. Educacion Fisica', 'Prof. de Educacion Fisica', 'Media jornada', 24, DATE '2020-08-01', 'Licencia', TRUE
    FROM "PERSONAS" p WHERE p."RUN" = '16.789.012-3'
    UNION ALL
    SELECT 'PROF-006', p."ID", 'Prof. Convivencia y Matematica', 'Prof. de Convivencia y Matematica', 'Jornada completa', 38, DATE '2024-03-01', 'Activo', TRUE
    FROM "PERSONAS" p WHERE p."RUN" = '17.890.123-4'
) seed("CODIGO", "PERSONA_ID", "ESPECIALIDAD", "TITULO_PROFESIONAL", "TIPO_CONTRATO", "HORAS_SEMANALES", "FECHA_INGRESO", "ESTADO_DOCENTE", "ACTIVO")
WHERE NOT EXISTS (
    SELECT 1 FROM "PROFESORES" pr WHERE pr."PERSONA_ID" = seed."PERSONA_ID"
);

INSERT INTO "PROFESOR_ASIGNATURAS" ("PROFESOR_ID", "ASIGNATURA_ID", "ACTIVO")
SELECT pr."ID", a."ID", TRUE
FROM (
    VALUES
        ('PROF-001', 'MAT'),
        ('PROF-001', 'CIE'),
        ('PROF-002', 'LEN'),
        ('PROF-002', 'HIS'),
        ('PROF-003', 'ART'),
        ('PROF-003', 'MUS'),
        ('PROF-004', 'ING'),
        ('PROF-005', 'EFI'),
        ('PROF-006', 'MAT'),
        ('PROF-006', 'CONV')
) AS seed("CODIGO_PROFESOR", "CODIGO_ASIGNATURA")
JOIN "PROFESORES" pr ON pr."CODIGO" = seed."CODIGO_PROFESOR"
JOIN "ASIGNATURAS" a ON a."CODIGO" = seed."CODIGO_ASIGNATURA"
WHERE NOT EXISTS (
    SELECT 1 FROM "PROFESOR_ASIGNATURAS" pa
    WHERE pa."PROFESOR_ID" = pr."ID" AND pa."ASIGNATURA_ID" = a."ID"
);

INSERT INTO "PROFESOR_CONTACTOS_EMERGENCIA" ("PROFESOR_ID", "NOMBRE_COMPLETO", "RELACION", "TELEFONO", "ACTIVO")
SELECT pr."ID", seed."NOMBRE_COMPLETO", seed."RELACION", seed."TELEFONO", TRUE
FROM (
    VALUES
        ('PROF-001', 'Ana Perez Silva', 'Conyuge', '+56 9 7000 1111'),
        ('PROF-002', 'Luis Gonzalez Soto', 'Hermano', '+56 9 7000 2222'),
        ('PROF-003', 'Patricia Vargas Diaz', 'Madre', '+56 9 7000 3333'),
        ('PROF-004', 'Rosa Soto Torres', 'Madre', '+56 9 7000 4444'),
        ('PROF-005', 'Marco Perez Vega', 'Pareja', '+56 9 7000 5555'),
        ('PROF-006', 'Claudio Ramirez Diaz', 'Padre', '+56 9 7000 6666')
) AS seed("CODIGO_PROFESOR", "NOMBRE_COMPLETO", "RELACION", "TELEFONO")
JOIN "PROFESORES" pr ON pr."CODIGO" = seed."CODIGO_PROFESOR"
WHERE NOT EXISTS (
    SELECT 1 FROM "PROFESOR_CONTACTOS_EMERGENCIA" pc WHERE pc."PROFESOR_ID" = pr."ID"
);
